+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Records new tickets and their stock movements together. */
+export function recordSales(store, rows) {
+  const staged = memoryStore(store.data);
+  const imported = new Set(staged.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const { row, ticket, soldAt, dishId, qty } of rows) {
+    const dish = (staged.data.dishes ?? []).find((entry) => entry.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${row}: unknown dish ${dishId}` });
+    if (imported.has(ticket)) continue;
+
+    let recipe;
+    try {
+      recipe = getRecipe(staged, dish.recipeId);
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row}: dish ${dishId} has no recipe` });
+    }
+    const ingredients = scaled(recipe, qty).filter((ingredient) => ingredient.qty > 0);
+    for (const { itemId, qty: needed } of ingredients) {
+      try {
+        consume(staged, itemId, needed, { at: soldAt, ref: `sale:${ticket}` });
+      } catch (error) {
+        if (!(error instanceof AppError)) throw error;
+        throw new AppError(error.code, { ...error.params, row });
+      }
+    }
+    staged.data.sales.push({ id: staged.nextId("sale"), ticket, soldAt, dishId, qty, ingredients });
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  if (tickets.size) store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
